from dataclasses import dataclass

from tdlm.aug.dag import Context, DagCampaign, Example, Instruction, Lines, ParseError, Result, Template


@dataclass(frozen=True)
class Record:
    id: str


@dataclass(frozen=True)
class AdRecord(Record):
    title: str
    description: str


@dataclass(frozen=True)
class AdContext(Context):
    head = "You read one search ad."
    title: str
    description: str


@dataclass(frozen=True)
class Tone(Result):
    value: str


@dataclass(frozen=True)
class Audience(Result):
    value: str


EX_1 = AdContext("Winter coats 50% off", "Warm down coats for the whole family. Free returns.")
EX_2 = AdContext("Pass the bar exam", "Online courses by former examiners. Start today.")


class ToneInstruction(Instruction[Tone]):
    context = AdContext
    instruction = "State the tone of the ad in one word."
    examples = (Example(EX_1, Tone("friendly")), Example(EX_2, Tone("urgent"), wrong=Tone("friendly"), why="'Start today' pushes to act now."))
    load = 1

    def render(self, ad: AdRecord) -> AdContext:
        return AdContext(ad.title, ad.description)

    def format(self, result: Tone) -> Lines:
        return {"tone": result.value}

    def parse(self, lines: Lines) -> Tone:
        if not isinstance(lines.get("tone"), str):
            raise ParseError("no tone line")
        return Tone(lines["tone"])


class AudienceInstruction(Instruction[Audience]):
    context = AdContext
    instruction = "Name the audience the ad addresses."
    examples = (Example(EX_1, Audience("families")), Example(EX_2, Audience("law students")))
    load = 1

    def render(self, ad: AdRecord) -> AdContext:
        return AdContext(ad.title, ad.description)

    def format(self, result: Audience) -> Lines:
        return {"audience": result.value}

    def parse(self, lines: Lines) -> Audience:
        if not isinstance(lines.get("audience"), str):
            raise ParseError("no audience line")
        return Audience(lines["audience"])


def parse_record(d: dict) -> AdRecord:
    return AdRecord(**d)


class AdCampaign(DagCampaign):
    def __init__(self) -> None:
        super().__init__(Template(record_base=Record, instructions=(ToneInstruction, AudienceInstruction)), parse_record=parse_record)

    def read_input(self, path):
        yield from path
EOF
